-- Keep historical attachment metadata while retiring completed storage work.
-- Existing soft-deleted rows stay pending: deletedAt did not prove physical deletion.
ALTER TABLE "Attachment" ADD COLUMN "storageDeletedAt" TIMESTAMP(3);

CREATE INDEX "Attachment_userId_storageDeletedAt_createdAt_id_idx"
ON "Attachment"("userId", "storageDeletedAt", "createdAt", "id");
